  kaynak:"Foundation of the Hellenic World, Hellenic History on the Internet, 'The Dictatorship of Pangalos' https://www.ime.gr/chronos/14/en/1923_1940/domestic_policy/facts/06.html : \"Theodoros Pangalos seized power by coup, on 25 June1925\"",
