  yer_kon:[78.22, 15.65],
  d:"1920 Svalbard Antlaşması'nın tanıdığı egemenlik, Svalbard Yasası'nın 14 Ağustos 1925'te yürürlüğe girmesiyle fiilen kuruldu. Takımadalar resmen Norveç Krallığı'nın parçası oldu; yüzölçümü Norveç'in Dovre'nin güneyindeki kesimi kadardır.",
