  gun:"22 Aralık 1925 (TDV Abdülazîz b. Suûd)",
  yer:"Cidde", yer_id:"Cidde",
  yer_kon:[21.49, 39.19],
  d:"Hâşimîler'in son kalesi Cidde de Abdülazîz'e geçti; Hicaz Krallığı fiilen sona erdi ve bütün Hicaz Suudi idaresine girdi. Abdülazîz 10 Ocak 1926'da Hicaz kralı ilân edildi.",
  kaynak:"TDV İslâm Ansiklopedisi 'ABDÜLAZÎZ b. SUÛD' https://islamansiklopedisi.org.tr/abdulaziz-b-suud : \"Ürdün ve Irak sınırları ile ilgili olarak İngilizler’le anlaşmalar yaptıktan sonra, Hâşimîler’in elinde kalan şehirlerden Medine (5 Aralık 1925) ve Cidde’yi de (22 Aralık) aldı.\" ; \"Bu zaferlerden sonra 10 Ocak 1926’da Hicaz kralı ilân edildi.\"",
