  yer_kon:[-34.6, -58.38],
  d:"Emekli General José Félix Uriburu'nun önderliğindeki askerî-sivil darbe, ikinci döneminde olan Cumhurbaşkanı Hipólito Yrigoyen'i devirdi. Arjantin'in 1930-43 'uğursuz on yılı' ve ordunun siyasete düzenli müdahalesi bu darbeyle başladı; Uriburu Şubat 1932'ye dek fiilî cumhurbaşkanı kaldı.",
