  yer:"Monrovia", yer_id:"Monrovia",
  yer_kon:[6.3, -10.8],
  d:"Milletler Cemiyeti uluslararası komisyonunun zorla çalıştırma soruşturması ve reform programına muhalefet üzerine Devlet Başkanı Charles D. B. King istifa etti. Dışişleri Bakanı Edwin Barclay devlet başkanlığını üstlendi.",
  kaynak:"FRUS 1930 vol. III, No. 349 (882.001/54), The Chargé in Liberia (Reber) to the Secretary of State, Monrovia 3 Aralık 1930 https://history.state.gov/historicaldocuments/frus1930v03/d349 (özet: King aynı öğleden sonra saat 3'te istifa edeceğini bildirdi; halefi Dışişleri Bakanı Edwin Barclay)",
