  kaynak:"TDV İslâm Ansiklopedisi 'Keşmir' https://islamansiklopedisi.org.tr/kesmir : \"1931'de Srinagar halkı polisin ateş açarak yirmi bir kişiyi öldürmesini protesto etmek için sokaklara döküldü.\"",
