  yer_kon:[27.71, 85.32],
  d:"Rana ailesinin kalıtsal başbakanlığında Bhim Şumşer'in (1929-32) ardından Cuddha Şumşer yönetimi devraldı. Muhafazakâr Cuddha 1945'e kadar görevde kaldı; bu dönemde ilk Nepal siyasî partisi Praca Pariṣad sürgünde kuruldu.",
  kaynak:"LOC Nepal 'The Ranas' http://countrystudies.us/nepal/15.htm (özet: Bhim Shamsher 1929-32, Juddha Shamsher 1932-45) · LOC Nepal 'The Growth of Political Parties' http://countrystudies.us/nepal/16.htm : \"By 1935 the first Nepalese political party, the Praja Parishad (People's Council), began among Nepalese exiles and set up cells within the country.\"",
