  d:"Lozan'da aidiyeti belirsiz kalan Meis'e bağlı adacıklar için Türkiye ile İtalya arasında yedi maddelik itilafname imzalandı. Bodrum körfezindeki Karaada Türkiye'de kaldı; Meis'e bağlı otuz adacıktan on dokuzu Türkiye'ye, on biri İtalya'ya verildi.",
  kaynak:"TDV İA 'Oniki Ada': \"iki devlet arasında 4 Ocak 1932’de Anadolu sahilleriyle Meis adası arasındaki ada ve adacıkların ... antlaşma daha imzalandı\" ve \"Meis adasına bağlı otuz adacıktan on dokuzu Türkiye’ye, on biri İtalya’ya verildi\"",
