  d:"Hava Kuvvetleri komutanı Marmaduke Grove'un önderliğindeki ayaklanma Cumhurbaşkanı Montero'yu düşürdü ve Puga-Matte-Dávila cuntasıyla Sosyalist Cumhuriyet'i kurdu. 16 Haziran'da Dávila, Matte ile Grove'u Paskalya Adası'na sürdü; rejim 13 Eylül 1932'de General Blanche'ın müdahalesiyle sona erdi ve seçimlerle Alessandri yeniden iktidara geldi.",
