  yer_kon:[34.53, 69.17],
  d:"Nâdir Şah şahsî bir düşmanı tarafından öldürüldü; kardeşlerinin desteğiyle oğlu Zâhir Şah kargaşa çıkmadan tahta geçti ve 1973'e kadar hüküm sürdü.",
  kaynak:"TDV İslâm Ansiklopedisi 'AFGANİSTAN' https://islamansiklopedisi.org.tr/afganistan : \"Kasım 1933’te şahsî bir düşmanı tarafından öldürülen Nâdir Şah’ın yerine, ülkede kargaşalık çıkmasına fırsat vermeyen kardeşlerinin desteğiyle, oğlu Zâhir Şah geçti.\"",
