  kaynak:"Pitt Rivers Museum (Oxford), The Tibet Album, 'Reting Rinpoche Biography' https://tibet.prm.ox.ac.uk/biography_291.html : \"In 1934 after the death of the Dalai Lama he was appointed Regent.\" · Office of His Holiness the Dalai Lama, 'Chronology of Events' https://www.dalailama.com/the-dalai-lama/events-and-awards/chronology-of-events (özet: 13. Dalai Lama Aralık 1933'te öldü) · PRM '13th Dalai Lama Biography' https://tibet.prm.ox.ac.uk/biography_336.html (ölüm yılı 1933)",
