  d:"Bir oylamadaki usul hatası üzerine Millî Meclis'in üç başkanı da istifa etti ve oturum kesildi. Başbakan Dollfuss oturumun yeniden toplanmasını polisle engelleyerek parlamentosuz, kararnameyle yönetime geçti; Birinci Cumhuriyet diktatörlüğe dönüştü.",
