  d:"Cumhurbaşkanı Gabriel Terra, Blanco lideri Herrera ile anlaşarak Genel Meclis'i ve kolektif yürütme organı Milli İdare Konseyi'ni dağıttı, kararnameyle yönetmeye başladı. 1934'te plebisitle kabul edilen yeni anayasa kolegial yürütmeyi kaldırdı; hafif otoriter yönetim 1938'e dek sürdü.",
