  d:"Almanya ve Polonya, aralarındaki sorunları kuvvete başvurmadan doğrudan görüşmelerle çözmeyi öngören on yıllık bir bildiri imzaladı. Piłsudski'nin iki büyük komşu arasında denge politikasının Alman ayağı buydu; Hitler 28 Nisan 1939'da bildiriyi feshetti.",
