  gun:"20 Temmuz 1936 (TDV Montrö Boğazlar Sözleşmesi)",
  yer:"Montrö",
  yer_kon:[46.43, 6.91],
  d:"22 Haziran 1936'da toplanan konferans, 1923 Lozan Boğazlar Sözleşmesi'nin silâhsızlandırma hükümlerini kaldıran Montrö Sözleşmesi ile sona erdi. Türkiye Boğazlar bölgesini yeniden askerîleştirme hakkı kazandı; sözleşme 9 Kasım 1936'da yürürlüğe girdi.",
