  kaynak:"Columbia Encyclopedia 6th ed. 'Metaxas, John' https://www.encyclopedia.com/reference/encyclopedias-almanacs-transcripts-and-maps/metaxas-john : \"With the support of King George II, Metaxas dissolved parliament on Aug. 4, 1936, and established a dictatorship\" · FHW Metaksas bildirisi https://www.ime.gr/chronos/14/en/1923_1940/domestic_policy/sources/metaxas.html (\"Athens 4 August 1936\")",
