  kaynak:"Encyclopedia.com 'Chiang Kai-shek' https://www.encyclopedia.com/people/history/chinese-and-taiwanese-history-biographies/chiang-kai-shek : 12 Aralık 1936'da Sian'da kaçırıldı (özet); LoC Country Studies 'China — Anti-Japanese War' http://countrystudies.us/china/22.htm : Aralık 1936'da Xi'an'da isyan (özet)",
