  d:"Londra'da imzalanan savunma, maliye ve ticaret anlaşmalarıyla İngiltere, Berehaven'daki Amirallik mülk ve haklarını ve Berehaven, Cobh (Queenstown) ve Lough Swilly liman savunmalarını Éire hükûmetine devretmeyi kabul etti. Devir en geç 31 Aralık 1938'de tamamlanacaktı. Böylece 1921 antlaşmasından kalan son İngiliz askerî varlığı İrlanda topraklarından çekildi.",
