  d:"Adanın Şîrâzî kökenli yerli halkını temsil eden Şîrâzî Derneği faaliyete geçti. Sultan Halîfe b. Harûb (1911-1960) döneminde, İngiliz himayesi altında toplulukların ayrı siyasi örgütlenmesi sürdü.",
  kaynak:"TDV İslâm Ansiklopedisi 'ZENGİBAR' https://islamansiklopedisi.org.tr/zengibar : \"1934’te Afrika Derneği (African Association), 1939’da Şîrâzî Derneği (Shirazi Association) faaliyete geçti.\"",
