  taraflar:["romanya-kralligi", "ingiltere", "fransa-cumhuriyet"],
  gun:"13 Nisan 1939 (LoC)",
  yer:"Bükreş", yer_id:"Bükreş",
  yer_kon:[44.43, 26.1],
  d:"Çekoslovakya'nın yıkılışı ve Arnavutluk'un işgali üzerine Fransa ve İngiltere Romanya'nın bağımsızlığına güvence verdi. Benzer bir Sovyet güvencesi, Romanya Kızılordu'nun topraklarından geçişine izin vermeyince sonuçsuz kaldı.",
  kaynak:"LoC Country Study Romania 'World War II' http://countrystudies.us/romania/22.htm : \"On April 13, 1939, France and Britain pledged to ensure the independence of Romania\"",
