  yer:"La Paz", yer_id:"La Paz",
  yer_kon:[-16.5, -68.15],
  d:"27 Mayıs 1938'de anayasal cumhurbaşkanı seçilen Germán Busch, reformlarının önündeki engeller karşısında kendini diktatör ilan etti ve 'askerî sosyalizm' programıyla radikal reformlara girişti. Aynı yıl 23 Ağustos'ta intihar etmesiyle rejim sona erdi.",
  kaynak:"Encyclopedia.com — 'Busch Becerra, Germán (1903–1939)' https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/busch-becerra-german-1903-1939 (özet) · LoC Country Studies http://countrystudies.us/bolivia/16.htm (özet)",
