  d:"Başbakan Phibun'un milliyetçi politikası çerçevesinde ülkenin adı Siyam'dan Tayland'a (Muang Thai) çevrildi. Aynı yıl yabancı sermayeyi kısan 'Tayland Taylılarındır' ekonomik programı başlatıldı.",
  kaynak:"EBSCO Research Starters 'Siam Changes Its Name to Thailand' https://www.ebsco.com/research-starters/history/siam-changes-its-name-thailand : ad ilk kez 5 Haziran 1939'da Tayland olarak değişti (özet); LoC Country Studies Thailand http://countrystudies.us/thailand/20.htm : 1939'da ad resmen Muang Thai olarak değişti (özet)",
