  yer_kon:[47.75, 118.6],
  d:"Mayıs 1939'da Mançukuo'daki Japon kuvvetleriyle başlayan çatışmalar Mayıs-Eylül arasında Halha Irmağı boyunca büyük kara ve hava savaşlarına dönüştü. Sovyet-Moğol kuvvetlerinin üstünlüğüyle çatışmalar 16 Eylül'de sona erdi; Moğolistan'ın doğu sınırı korundu.",
  kaynak:"LOC Mongolia http://countrystudies.us/mongolia/30.htm : \"Between May and September 1939, there was large-scale ground and aerial fighting along the Khalkhyn Gol.\" \"Hostilities ended on September 16, 1939.\"",
