  d:"Almanya'nın 1 Eylül saldırısından on altı gün sonra Sovyetler Birliği doğu Polonya'yı işgal etti; Polonya hükûmeti aynı gün ülkeyi terk etti. 28 Eylül'de iki devlet Polonya'yı gizli protokol doğrultusunda Bug hattı boyunca paylaştı. Haritada Polonya'nın doğu yarısı Sovyet yönetimine geçti.",
