  yer_kon:[55.76, 37.62],
  d:"Sovyet baskısı altında Estonya on yıllık karşılıklı yardım antlaşmasını imzaladı. Antlaşma Sovyetlere Saaremaa (Ösel) ve Hiiumaa (Dagö) adalarında ve Paldiski'de deniz ve hava üsleri kurma hakkı verdi; ABD Moskova büyükelçisi bunu fiilen bir Sovyet askerî himayesi olarak nitelendirdi.",
