  yer:"Lhasa (Potala)", yer_id:"Lhasa",
  yer_kon:[29.66, 91.12],
  d:"Tenzin Gyatso, 14. Dalai Lama olarak Potala Sarayı'nda düzenlenen törenle tahta çıkarıldı ve aynı yıl manastır eğitimine başladı. Yönetim reşit oluncaya dek naiplerde kaldı.",
  kaynak:"Office of His Holiness the Dalai Lama, 'Chronology of Events' https://www.dalailama.com/the-dalai-lama/events-and-awards/chronology-of-events : \"Enthronement Ceremony\" (22 Şubat 1940) · Encyclopedia.com 'Dalai Lama' (Encyclopedia of Religion) https://www.encyclopedia.com/people/philosophy-and-religion/buddhism-biographies/dalai-lama : \"he was enthroned in the Potala at Lhasa in 1940.\"",
