  d:"Norveç ve Danimarka'nın işgalinden sonra Almanya'nın İzlanda'yı ele geçirmesinden çekinen İngiltere, 10 Mayıs 1940'ta adayı İzlanda hükûmetinin rızası olmadan işgal etti. İzlanda böylece Kuzey Atlantik'te Müttefik stratejisinin kilit noktası oldu.",
