  d:"Başbakan Paul Reynaud 16 Haziran 1940'ta istifa ederek yerini Mareşal Philippe Pétain'e bıraktı. Pétain Almanya'dan ateşkes şartlarını istedi; bu adım 22 Haziran ateşkesine ve Temmuz'da III. Cumhuriyet'in fiilen sona ermesine giden yolu açtı.",
