  gun:"3 Temmuz 1940 (Hansard 4 Temmuz 1940)",
  yer:"Mers-el-Kébir",
  yer_kon:[35.73, -0.72],
  d:"Fransız donanmasının Almanya'nın eline geçmesini önlemek isteyen İngiltere, 3 Temmuz sabahı Fransız filosunun büyük bölümünü denetimine aldı. Oran ve Mers-el-Kébir'deki gemilere seçenekler sunuldu; reddedilince Amiral Somerville komutasındaki İngiliz filosu ateş açtı. Olay, İngiltere ile Pétain hükûmeti arasındaki ilişkileri kopma noktasına getirdi.",
