  gun:"3 Ağustos 1940 istilâ · 19 Ağustos 1940 tahliye (EBSCO)",
  yer:"Berbera", yer_id:"Berbera",
  yer_kon:[10.44, 45.01],
  d:"3 Ağustos'ta İtalyan Doğu Afrikası'ndan başlayan istilâ sonucunda İngiliz birlikleri 19 Ağustos'ta Berbera'dan Aden'e tahliye edildi. İngiliz Somalisi İtalyan Doğu Afrikası'na katıldı; Somali kabileleri kırk yıl sonra ilk kez tek idarede birleşti.",
