  kaynak:"OH 'The Atlantic Conference & Charter, 1941' https://history.state.gov/milestones/1937-1945/atlantic-conf : görüşme 9-10 Ağustos, bildirge 14 Ağustos 1941 (özet) · Avalon 'Atlantic Charter' https://avalon.law.yale.edu/wwii/atlantic.asp",
