  yer_kon:[51.51, -0.13],
  d:"28 Kasım'da verilen ve Sovyetler Birliği'ne karşı harekâtın 5 Aralık'a kadar durdurulmasını isteyen ültimatom yanıtsız kalınca İngiltere, Finlandiya, Romanya ve Macaristan'a 7 Aralık 1941 gece yarısından bir dakika sonra (GMT) geçerli olmak üzere savaş ilan etti. ABD ise Finlandiya ile savaşa girmedi.",
  kaynak:"Hansard, 'Finland, Hungary and Rumania' (HC Deb 10 Dec 1941) https://api.parliament.uk/historic-hansard/commons/1941/dec/10/finland-hungary-and-rumania : savaş ilanı '7 Aralık gece yarısından bir dakika sonra, GMT' itibarıyla; ültimatom 28 Kasım, süre 5 Aralık (özet)",
