  d:"İşgal altındaki Norveç'te Almanlar, 1933'te Nazi Partisi örneğinde faşist bir örgüt kurmuş olan Vidkun Quisling'i 1 Şubat 1942'de başbakanlığa getirdi. Kral VII. Haakon ve meşru hükûmet Londra'da sürgünde kalırken Quisling yönetimi Yahudilerin kaydını ve mallarına el konmasını uyguladı.",
