  d:"Londra'dan gönderilen Çekoslovak paraşütçüler Prag'da vekil Reich Protektörü Reinhard Heydrich'in arabasına saldırdı. Heydrich yarasından gelişen enfeksiyonla 4 Haziran 1942'de öldü; ardından Protektora'da kitlesel tutuklama ve infazlar başladı.",
