  kaynak:"Historisches Lexikon der Schweiz 'Zweiter Weltkrieg' https://hls-dhs-dss.ch/de/articles/008927/ : \"Der gravierendste Zwischenfall war die Bombardierung von Schaffhausen am 1. April 1944 mit 40 Toten, über 100 Verletzten und dem Verlust von Kulturgütern.\"",
