  yer_kon:[55.76, 37.62],
  d:"Finlandiya, Birleşmiş Milletler adına hareket eden SSCB ve Birleşik Krallık ile Moskova'da mütareke imzaladı. 1940 Moskova Barışı yeniden yürürlüğe kondu; Petsamo ili Sovyetler Birliği'ne geri verildi ve Porkkala-Udd 50 yıllığına Sovyet deniz üssü olarak kiralandı. Finlandiya'nın ağır savaş tazminatı ödemesi ve Alman kuvvetlerini ülkeden çıkarması şart koşuldu.",
