  yer_kon:[48.21, 16.37],
  d:"Karl Renner'in geçici hükûmeti Anschluss'u hükümsüz ilan etti ve 1929 değişiklikli 1920 anayasasıyla bağımsız, demokratik Avusturya Cumhuriyeti'ni yeniden kurdu. Almanya henüz teslim olmamıştı; Batılı Müttefikler hükûmeti bir süre tanımadı.",
