  taraflar:["siyam-chakri", "ingiltere", "abd"],
  gun:"16 Ağustos 1945 (FRUS 1945 c. VI, d. 957)",
  yer:"Bangkok", yer_id:"Bangkok (Tonburi)",
  yer_kon:[13.75, 100.5],
  d:"Naip Pridi'nin barış bildirisi 1942 savaş ilanını anayasaya aykırı ve hükümsüz saydı; 1943'te alınan Malay ve Şan eyaletlerinin İngiltere'ye iade edileceği açıklandı. Çinhindi'nden alınan topraklar için Tayland BM usullerini istedi.",
  kaynak:"FRUS 1945 c. VI d. 957 (Moffat görüşme notu, 24 Ağustos 1945) https://history.state.gov/historicaldocuments/frus1945v06/d957 : 16 Ağustos 1945 Tay barış bildirisinin Malay ve Şan eyaletlerinin İngiltere'ye iadesini öngördüğü (özet); FRUS 1945 c. VI d. 924 : Naip savaş ilanını anayasaya aykırı ve hükümsüz ilan eder (özet)",
